package application_test
import ("context"; "errors"; "testing"; "time"; "evidence/internal/application"; "evidence/internal/domain"; "evidence/internal/repository")
func TestBug05CyclicDelegationCannotEnable(t *testing.T){ctx:=context.Background(); repo,_:=repository.NewFileRepository(t.TempDir()); scope:=domain.ResourceScope{Type:"doc",Identifier:"x"}; exp:=time.Now().Add(time.Hour); for _,id:=range []string{"a","b","c"}{_ = repo.SaveConditionVersion(ctx,domain.ConditionVersion{ID:"cv-"+id,RequestID:id,Scope:scope}); st:=domain.StatusEnabled; if id=="a"{st=domain.StatusUnderReview}; _=repo.SaveRequest(ctx,domain.AuthorizationRequest{ID:id,Status:st,CurrentVersionID:"cv-"+id,ExpiresAt:&exp,Version:1,DelegationChainID:"chain"})}; chain:=domain.DelegationChain{ID:"chain",Nodes:[]domain.DelegationNode{{RequestID:"a",ParentRequestID:"c",AllowedScope:scope},{RequestID:"b",ParentRequestID:"a",AllowedScope:scope},{RequestID:"c",ParentRequestID:"b",AllowedScope:scope}}}; _=repo.SaveDelegationChain(ctx,chain); err:=application.NewAuthorizationService(repo).Enable(ctx,"a","u"); if !errors.Is(err,domain.ErrDelegationCycle){t.Fatalf("cycle accepted: %v",err)}}
